package com.nigson.acceptance.fulfillment;
import com.nigson.commerce.fulfillment.*;
import com.nigson.shared.events.EventCodec;
import org.junit.jupiter.api.Test;
import java.util.*;
import static org.assertj.core.api.Assertions.*;
class FulfillmentValuesTest {
 private static final UUID ID=UUID.fromString("00000000-0000-0000-0000-000000000001");
 private FulfillmentValues.Rule r(String region,String postal,int priority){return new FulfillmentValues.Rule(UUID.randomUUID(),ID,"NG",region,postal,"12.34",null,priority,true,0);}
 @Test void specificityOutranksPriorityAndEqualOverlapsAreAmbiguous(){FulfillmentValues.Rule broad=r(null,null,100),regional=r("SYNTH_REGION",null,-100),postal=r(null,"12",0),both=r("SYNTH_REGION","12",0),longer=r("SYNTH_REGION","123",-100);assertThat(DeliverySpecificity.select(List.of(broad,regional),"NG","SYNTH_REGION","12345")).isEqualTo(regional);assertThat(DeliverySpecificity.select(List.of(both,longer,postal,regional,broad),"NG","SYNTH_REGION","12345")).isEqualTo(longer);assertThat(DeliverySpecificity.ambiguous(broad,r(null,null,100))).isTrue();assertThat(DeliverySpecificity.ambiguous(regional,r("OTHER_REGION",null,-100))).isFalse();assertThat(DeliverySpecificity.ambiguous(postal,r(null,"13",0))).isFalse();assertThat(DeliverySpecificity.ambiguous(both,longer)).isFalse();assertThatThrownBy(()->DeliverySpecificity.select(List.of(broad,r(null,null,100)),"NG",null,null)).hasMessage("FULFILLMENT_RULE_VIOLATION");assertThatThrownBy(()->DeliverySpecificity.select(List.of(regional),"NG","OTHER_REGION",null)).hasMessage("FULFILLMENT_RULE_VIOLATION");}
 @Test void closesMoneyRegionAndOptionalInputs(){String body="{\"marketId\":\""+ID+"\",\"countryCode\":\"NG\",\"fee\":\"12.34\",\"priority\":-1,\"active\":false}";assertThat(FulfillmentValues.deliveryRule(EventCodec.JSON.readTree(body)).fee()).isEqualTo("12.34");for(String bad:List.of(body.replace("12.34","12.340"),body.replace("\"NG\"","\"US\"")))assertThatThrownBy(()->FulfillmentValues.deliveryRule(EventCodec.JSON.readTree(bad))).hasMessage("FULFILLMENT_RULE_VIOLATION");for(String bad:List.of(body.replace("12.34","-1.00"),body.replace("-1,","1.0,"),body.replace("false}","false,\"regionCode\":null}"),body.replace("false}","false,\"currency\":\"USD\"}")))assertThatThrownBy(()->FulfillmentValues.deliveryRule(EventCodec.JSON.readTree(bad))).hasMessage("VALIDATION_ERROR");}
 @Test void shipmentsAndReturnsAreBoundedAndCannotSpoofFedexProof(){String row="{\"orderLineId\":\""+ID+"\",\"balanceId\":\""+ID+"\",\"quantity\":\"2\"}";String body="{\"lines\":["+row+"]}";assertThat(FulfillmentValues.shipment(EventCodec.JSON.readTree(body)).provider()).isEqualTo("MANUAL");assertThatThrownBy(()->FulfillmentValues.shipment(EventCodec.JSON.readTree(body.replace("]}","],\"provider\":\"FEDEX\",\"providerReference\":\"browser-claim\"}")))).hasMessage("FULFILLMENT_RULE_VIOLATION");assertThatThrownBy(()->FulfillmentValues.shipment(EventCodec.JSON.readTree("{\"lines\":["+row+","+row+"]}"))).hasMessage("VALIDATION_ERROR");assertThatThrownBy(()->FulfillmentValues.shipment(EventCodec.JSON.readTree(body.replace("\"2\"","\"0\"")))).hasMessage("VALIDATION_ERROR");String physical=body.replace("]}","],\"kind\":\"PHYSICAL_RETURN\",\"reason\":\"Synthetic receipt verification\"}");assertThatThrownBy(()->FulfillmentValues.returned(EventCodec.JSON.readTree(physical))).hasMessage("VALIDATION_ERROR");assertThat(FulfillmentValues.returned(EventCodec.JSON.readTree(physical.replace("PHYSICAL_RETURN","UNSHIPPED_CANCEL"))).receiptReference()).isNull();for(String url:List.of("http://tracking.synthetic.test/","https://user@tracking.synthetic.test/","https://tracking.synthetic.test/#token","https://tracking.synthetic.test:8443/"))assertThatThrownBy(()->FulfillmentValues.https(url)).hasMessage("VALIDATION_ERROR");}
 @Test void providerPolicyIsDisabledByDefaultAndCannotUseMocksInProduction(){var clock=java.time.Clock.systemUTC();var disabled=new FulfillmentPolicy(false,"test","",null,null,null,Set.of(),clock);assertThatThrownBy(()->disabled.require("MOCK","FEDEX")).hasMessage("PROVIDER_UNAVAILABLE");assertThatThrownBy(()->new FulfillmentPolicy(true,"prod","MOCK","SYNTHETIC_NOT_QUALIFIED",java.time.Instant.now().plusSeconds(300),null,Set.of(),clock)).hasMessage("FULFILLMENT_PROVIDER_CONFIGURATION_INVALID");var active=new FulfillmentPolicy(true,"test","MOCK","SYNTHETIC_NOT_QUALIFIED",java.time.Instant.now().plusSeconds(300),null,Set.of("tracking.synthetic.invalid"),clock);assertThatThrownBy(()->active.require("LIVE","FEDEX")).hasMessage("PROVIDER_MODE_MISMATCH");assertThatThrownBy(()->active.require("MOCK","MANUAL")).hasMessage("FULFILLMENT_RULE_VIOLATION");assertThatThrownBy(()->active.tracking("https://attacker.invalid/")).hasMessage("FULFILLMENT_RULE_VIOLATION");}

 @Test void actualHandoverIsOptionalAndCannotAcceptNullOrUnknownEvidence(){String body="{\"reason\":\"Synthetic physical handover receipt\"}";assertThat(FulfillmentValues.dispatch(EventCodec.JSON.readTree(body)).dispatchedAt()).isNull();String at="2026-10-15T23:00:00.123456789Z";assertThat(FulfillmentValues.dispatch(EventCodec.JSON.readTree(body.replace("}",",\"dispatchedAt\":\""+at+"\"}"))).dispatchedAt()).isEqualTo(java.time.Instant.parse(at));for(String extra:List.of("\"dispatchedAt\":null","\"dispatchedAt\":123","\"dispatchedAt\":\"yesterday\"","\"deliveredAt\":\""+at+"\"","\"dispatchedAt\":\"2026-10-15\""))assertThatThrownBy(()->FulfillmentValues.dispatch(EventCodec.JSON.readTree(body.replace("}",","+extra+"}")))).hasMessage("VALIDATION_ERROR");}

}
